import { createVNode, Fragment } from '../create-element';
import { isArray } from '../util';
import { setStyle } from './props';

/**
 * Normalize a child from a render result into a VNode (or null).
 * @param {ComponentChild} childVNode
 * @returns {VNode | null}
 */
export function coerceChildVNode(childVNode) {
	if (
		childVNode == null ||
		typeof childVNode == 'boolean' ||
		typeof childVNode == 'function'
	) {
		return null;
	}
	// If this newVNode is being reused (e.g. <div>{reuse}{reuse}</div>) in the same diff,
	// or we are rendering a component (e.g. setState) copy the oldVNodes so it can have
	// it's own DOM & etc. pointers
	if (
		typeof childVNode == 'string' ||
		typeof childVNode == 'number' ||
		// eslint-disable-next-line valid-typeof
		typeof childVNode == 'bigint' ||
		childVNode.constructor == String
	) {
		return createVNode(null, childVNode, null, null, null);
	}
	if (isArray(childVNode)) {
		return createVNode(Fragment, { children: childVNode }, null, null, null);
	}
	if (childVNode.constructor === undefined && childVNode._depth > 0) {
		// VNode is already in use, clone it. This can happen in the following
		// scenario:
		//   const reuse = <div />
		//   <div>{reuse}<span />{reuse}</div>
		return createVNode(
			childVNode.type,
			childVNode.props,
			childVNode.key,
			childVNode.ref ? childVNode.ref : null,
			childVNode._original
		);
	}
	return childVNode;
}

/**
 * Flatten and loop through the children of a virtual node
 * @param {ComponentChildren} children The unflattened children of a virtual
 * node
 * @returns {VNode[]}
 */
export function toChildArray(children, out) {
	out = out || [];
	if (children == null || typeof children == 'boolean') {
	} else if (isArray(children)) {
		children.some(child => {
			toChildArray(child, out);
		});
	} else {
		out.push(children);
	}
	return out;
}

/**
 * Apply a single CSS property onto a DOM style declaration.
 * @param {CSSStyleDeclaration} style
 * @param {string} key
 * @param {string | number | null | undefined} value
 */
export function applyHostStyle(style, key, value) {
	setStyle(style, key, value);
}

