/**
 * Invoke or update a ref, depending on whether it is a function or object ref.
 * @param {Ref<any>} ref
 * @param {any} value
 * @param {VNode} vnode The vnode whose cleanup function should be invoked
 * @param {VNode} [errorVNode] The vnode to use when reporting errors
 */
applyRef(ref, value, vnode, errorVNode) {
	try {
		if (typeof ref == 'function') {
			const cleanup = vnode._cleanup;
			vnode._cleanup = undefined;

			if (typeof cleanup == 'function') {
				cleanup();
			}

			// When a cleanup function was returned, the ref is not invoked
			// with `null` on unmount.
			if (value != null || typeof cleanup != 'function') {
				const result = ref(value);
				if (typeof result == 'function') {
					vnode._cleanup = result;
				}
			}
		} else {
			ref.current = value;
		}
	} catch (e) {
		this._hooks._catchError(e, errorVNode || vnode);
	}
}

